{
  "tool": "type_text",
  "control": 3,
  "text": "{{core_username}}",
  "intent": "Enter the username to sign into the application."
}

{
  "tool": "type_text",
  "control": 5,
  "text": "{{core_password}}",
  "intent": "Enter the password to sign into the application."
}

{
  "tool": "click",
  "control": 6,
  "intent": "Sign on to the Meridian Core application using the provided credentials."
}

{
  "tool": "click",
  "control": 5,
  "intent": "Navigate to the Member Search function to look up member 10021."
}

{
  "tool": "type_text",
  "control": 14,
  "text": "10021",
  "intent": "Enter the member number 10021 into the Member Number field."
}

{
  "tool": "click",
  "control": 15,
  "intent": "Search for member 10021 using the Member Number field."
}

{
  "tool": "click",
  "control": 17,
  "intent": "Open the member record for member 10021 to view their account details."
}

{
  "tool": "click",
  "control": 16,
  "intent": "Navigate to the Accounts section to view the member's account details."
}

{
  "tool": "finish",
  "summary": "Looked up member 10021 and read their Regular Savings balance and account number.",
  "outcomes": [
    {
      "name": "Member not found",
      "description": "The member record does not exist in the system.",
      "disposition": "answer"
    },
    {
      "name": "Access denied",
      "description": "The user does not have permission to view the member's account details.",
      "disposition": "needs_human"
    },
    {
      "name": "Session expired",
      "description": "The user's session has expired, and they need to sign in again.",
      "disposition": "needs_human"
    },
    {
      "name": "Error page",
      "description": "An unexpected error occurred while retrieving the member's account details.",
      "disposition": "needs_human"
    }
  ]
}
